#!/usr/bin/env python3
"""Publica artigos automáticos somente dentro de /blog/<slug>/ e reconstrói /blog/."""
from __future__ import annotations
import argparse, datetime as dt, html, json, re
from pathlib import Path
from typing import Any

ROOT=Path(__file__).resolve().parents[1]
BASE_URL='https://docegestor.github.io'
QUEUE=ROOT/'data/artigos_pendentes.json'
REGISTRY=ROOT/'data/artigos_publicados_estaticos.json'
LEGACY_REGISTRY=ROOT/'data/artigos_automatizados.json'
MARKET_URL='https://www.mercadolivre.com.br/docegestor-sistema-para-confeitaria--precificacao-e-vendas/up/MLBU4686356819?pdp_filters=item_id:MLB7401439782'
CATEGORIES=['Receitas e produtos','Precificação','Organização de encomendas','Gestão financeira','Vendas e marketing']


def esc(v: Any) -> str: return html.escape(str(v or ''), quote=True)
def load(p: Path, default: Any) -> Any:
    if not p.exists(): return default
    return json.loads(p.read_text(encoding='utf-8'))
def slugify(v: str) -> str:
    table=str.maketrans('áàâãéêíóôõúüçÁÀÂÃÉÊÍÓÔÕÚÜÇ','aaaaeeiooouucAAAAEEIOOOUUC')
    return re.sub(r'[^a-z0-9]+','-',v.translate(table).lower()).strip('-')[:90]
def normalize(raw: dict[str,Any]) -> dict[str,Any]:
    a=dict(raw); a['title']=str(a.get('title') or a.get('titulo') or '').strip(); a['description']=str(a.get('description') or a.get('descricao') or a.get('meta_description') or '').strip(); a['intro']=str(a.get('intro') or a.get('introduction') or a['description']).strip(); a['category']=str(a.get('category') or a.get('categoria') or CATEGORIES[1]).strip(); a['conclusion']=str(a.get('conclusion') or a.get('conclusao') or '').strip(); a['slug']=slugify(str(a.get('slug') or a['title']))
    if a['category'] not in CATEGORIES: a['category']=CATEGORIES[1]
    sections=[]
    for s in (a.get('sections') or a.get('secoes') or []):
        if isinstance(s,str): sections.append({'heading':'Seção','paragraphs':[s],'bullets':[]}); continue
        ps=s.get('paragraphs') or s.get('paragrafos') or s.get('content') or []; bs=s.get('bullets') or s.get('lista') or []
        if isinstance(ps,str): ps=[ps]
        if isinstance(bs,str): bs=[bs]
        sections.append({'heading':str(s.get('heading') or s.get('titulo') or 'Seção').strip(),'paragraphs':[str(x).strip() for x in ps if str(x).strip()],'bullets':[str(x).strip() for x in bs if str(x).strip()]})
    a['sections']=sections; faq=a.get('faq') or a.get('perguntas_frequentes') or []; a['faq']=[{'question':str(x.get('question') or x.get('pergunta') or '').strip(),'answer':str(x.get('answer') or x.get('resposta') or '').strip()} for x in faq if isinstance(x,dict)]
    return a
def validate(a:dict[str,Any]):
    if any(not a.get(k) for k in ('title','description','intro','conclusion','slug')): raise RuntimeError('Artigo sem campos obrigatórios.')
    if len(a['title'])>65 or len(a['description'])>170 or len(a['sections'])<4: raise RuntimeError('Artigo fora do padrão SEO: título, descrição ou seções inválidos.')
    if any(not s['heading'] or not s['paragraphs'] for s in a['sections']): raise RuntimeError('Cada seção precisa de título e parágrafo.')
def write_cover(path:Path,title:str,category:str):
    t=esc(title[:70]); c=esc(category[:35]); path.write_text(f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 900" role="img" aria-labelledby="t d"><title id="t">{t}</title><desc id="d">{c} — DoceGestor</desc><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff7f3"/><stop offset="1" stop-color="#ffd6c8"/></linearGradient></defs><rect width="1600" height="900" fill="url(#g)"/><circle cx="1310" cy="180" r="210" fill="#f4775b" opacity=".18"/><circle cx="1450" cy="700" r="310" fill="#e65f47" opacity=".12"/><text x="110" y="180" font-family="Georgia" font-size="42" fill="#e65f47">{c}</text><text x="110" y="330" font-family="Georgia" font-weight="700" font-size="74" fill="#3b1f1b">DoceGestor</text><text x="110" y="445" font-family="Arial" font-size="38" fill="#5b3a35">{t}</text><text x="110" y="780" font-family="Arial" font-size="28" fill="#5b3a35">Gestão simples para confeiteiras</text></svg>''',encoding='utf-8')
def nav()->str:
    return f'''<div class="topbar"><strong>Doce &amp; Lucro</strong><a href="https://t.me/docelucro">Gestão simples para quem transforma ingredientes em renda. <span>Entrar na comunidade →</span></a></div><header class="header"><a class="brand" href="/"><span>DG</span> DoceGestor</a><nav><a href="/">Início</a><a href="/blog/">Blog</a><a href="/receitas/">Receitas</a><a href="/ebooks/">E-books</a><a href="/#recursos">Recursos</a><a href="/#como-funciona">Como funciona</a><a class="buy" href="{MARKET_URL}" rel="sponsored noopener">Conhecer o app</a></nav></header>'''
def render(a:dict[str,Any],published:str,related:list[dict[str,Any]],image:str)->str:
    canonical=f'{BASE_URL}/blog/{a["slug"]}/'; sections=[]
    for i,s in enumerate(a['sections']):
        ps=''.join(f'<p>{esc(x)}</p>' for x in s['paragraphs']); bs=''.join(f'<li>{esc(x)}</li>' for x in s['bullets']); sections.append(f'<section id="sec-{i}"><h2>{esc(s["heading"])}</h2>{ps}{("<ul>"+bs+"</ul>") if bs else ""}</section>')
    faq=''.join(f'<h3>{esc(x["question"])}</h3><p>{esc(x["answer"])}</p>' for x in a['faq'] if x['question'] and x['answer']); related_html=''.join(f'<li><a href="/blog/{esc(x["slug"])}/">{esc(x["title"])}</a></li>' for x in related[:4])
    schema={'@context':'https://schema.org','@type':'BlogPosting','headline':a['title'],'description':a['description'],'image':[image],'datePublished':published,'dateModified':published,'author':{'@type':'Organization','name':'Equipe DoceGestor'},'publisher':{'@type':'Organization','name':'DoceGestor'},'articleSection':a['category'],'mainEntityOfPage':{'@type':'WebPage','@id':canonical}}
    css='''*{box-sizing:border-box}body{margin:0;background:#fffaf8;color:#3b1f1b;font:17px/1.75 DM Sans,Arial,sans-serif}.topbar{background:#fff7f3;border-bottom:1px solid #f6ddd5;padding:9px 24px;display:flex;justify-content:space-between;font-size:13px}.topbar a{color:#e65f47;text-decoration:none}.header{max-width:1152px;margin:auto;min-height:72px;padding:0 24px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{font-weight:800;font-size:20px;color:#3b1f1b;text-decoration:none}.brand span{color:#e65f47}.header nav{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.header nav a{color:#5b3a35;text-decoration:none;font-size:14px;font-weight:700;padding:8px 10px;border-radius:8px}.header nav a:hover{background:#fff1ed}.header .buy{background:#e65f47;color:white;padding:10px 15px}.article{max-width:860px;margin:auto;padding:34px 24px 70px}.back{font-size:14px;color:#806b65}.category{color:#e65f47;text-transform:uppercase;letter-spacing:.1em;font-weight:800;font-size:13px;margin-top:28px}.article h1{font:800 50px/1.1 Playfair Display,Georgia,serif;margin:10px 0 18px}.lead{font-size:21px;color:#654a45}.meta{font-size:14px;color:#806b65}.cover{width:100%;height:auto;border-radius:22px;margin:26px 0 8px;box-shadow:0 16px 40px #3b1f1b1f}.caption{font-size:13px;color:#806b65}.toc,.cta{background:#fff1ed;border:1px solid #f2cfc5;border-radius:16px;padding:18px 24px;margin:28px 0}.article h2{font:700 31px/1.2 Playfair Display,Georgia,serif;margin-top:42px}.article h3{font-size:21px;margin-top:26px}.article a{color:#d9553c}.cta strong{font:700 24px Playfair Display,Georgia,serif}.footer{border-top:1px solid #f2d9d1;text-align:center;padding:26px;color:#806b65;font-size:14px}@media(max-width:700px){.topbar,.header{padding-left:16px;padding-right:16px}.header{align-items:flex-start;flex-direction:column;padding-top:14px;padding-bottom:14px}.article{padding:25px 18px 55px}.article h1{font-size:38px}}'''
    return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f4775b"><meta name="robots" content="index,follow"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><title>{esc(a['title'])} | DoceGestor</title><meta name="description" content="{esc(a['description'])}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="article"><meta property="og:title" content="{esc(a['title'])}"><meta property="og:description" content="{esc(a['description'])}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{image}"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700;800&display=swap" rel="stylesheet"><style>{css}</style></head><body>{nav()}<main class="article"><a class="back" href="/blog/">← Voltar para o blog</a><div class="category">{esc(a['category'])}</div><h1>{esc(a['title'])}</h1><p class="lead">{esc(a['intro'])}</p><p class="meta">{dt.date.fromisoformat(published).strftime('%d/%m/%Y')} · 6 min de leitura · Por Equipe DoceGestor</p><img class="cover" src="{image}" alt="Imagem relacionada a {esc(a['title'])}" width="1600" height="900"><div class="caption">Conteúdo educativo para gestão de confeitaria.</div><div class="toc"><strong>Neste artigo</strong><ul>{''.join(f'<li><a href="#sec-{i}">{esc(s["heading"])}</a></li>' for i,s in enumerate(a['sections']))}</ul></div>{''.join(sections)}<section><h2>Perguntas frequentes</h2>{faq}</section><section><h2>Conclusão</h2><p>{esc(a['conclusion'])}</p></section><section class="cta"><strong>Do papel para o celular</strong><p>Precifique com mais segurança no DoceGestor. Acompanhe custos, vendas e lucro em um só lugar.</p><a href="{MARKET_URL}" rel="sponsored noopener">Conhecer o app →</a></section><section><h2>Leia também</h2><ul>{related_html}</ul></section></main><footer class="footer">DoceGestor · Gestão simples para confeitarias · <a href="/">Início</a> · <a href="/receitas/">Receitas</a> · <a href="/ebooks/">E-books</a> · Desenvolvido por <a href="https://saulomgg.github.io" target="_blank" rel="noopener noreferrer">saulomgg</a></footer></body></html>'''
def render_blog(registry:list[dict[str,Any]])->str:
    cards=''.join(f'<a class="card" href="/blog/{esc(x["slug"])}/"><img src="{esc(x.get("image") or ("/blog/"+x["slug"]+"/capa.svg" if (ROOT/"blog"/x["slug"]/"capa.svg").exists() else "/favicon.svg"))}" alt="Imagem de {esc(x["title"])}"><div class="card-cat">{esc(x.get("category","Gestão financeira"))}</div><h2>{esc(x["title"])}</h2><p>{esc(x["description"])}</p><div class="card-meta">{x.get("published","")} · 6 min de leitura · Por Equipe DoceGestor</div><b>Ler artigo →</b></a>' for x in registry)
    return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f4775b"><meta name="robots" content="index,follow"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><title>Blog DoceGestor | Precificação e gestão para confeitaria</title><meta name="description" content="Guias práticos para calcular preços, organizar encomendas, controlar custos e aumentar o lucro da sua confeitaria."><link rel="canonical" href="{BASE_URL}/blog/"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700;800&display=swap" rel="stylesheet"><style>body{{margin:0;background:#fffaf8;color:#3b1f1b;font:16px/1.6 DM Sans,Arial,sans-serif}}.topbar,.header{{padding:10px 24px;display:flex;justify-content:space-between;align-items:center}}.topbar{{background:#fff7f3;border-bottom:1px solid #f6ddd5;font-size:13px}}.topbar a,.header a{{color:#e65f47;text-decoration:none}}.header{{max-width:1152px;margin:auto;min-height:66px;gap:24px}}.brand{{font-size:20px;font-weight:800;color:#3b1f1b!important}}.brand span{{color:#e65f47}}nav{{display:flex;gap:6px;align-items:center;flex-wrap:wrap}}nav a{{color:#5b3a35!important;font-size:14px;font-weight:700;padding:8px 10px;border-radius:8px}}nav .buy{{background:#e65f47;color:#fff!important}}.hero{{background:#f7eee9;padding:75px 24px 82px}}.hero-inner{{max-width:1152px;margin:auto}}.eyebrow,.card-cat{{color:#e65f47;text-transform:uppercase;letter-spacing:.1em;font-size:12px;font-weight:800}}.hero h1{{max-width:800px;font:800 64px/1.03 Playfair Display,Georgia,serif;margin:14px 0}}.hero h1 em{{color:#e65f47;font-style:normal}}.hero p{{max-width:650px;color:#654a45;font-size:18px}}.cards{{max-width:1152px;margin:0 auto;padding:48px 24px 80px;display:grid;grid-template-columns:repeat(3,1fr);gap:20px}}.card{{display:flex;flex-direction:column;min-height:240px;padding:24px;border:1px solid #f2cfc5;border-radius:18px;background:#fff;color:#3b1f1b;text-decoration:none;box-shadow:0 8px 22px #3b1f1b0d}}.card img{{width:calc(100% + 48px);height:160px;object-fit:cover;margin:-24px -24px 18px;border-radius:18px 18px 0 0;background:#fff1ed}}.card:hover{{transform:translateY(-3px);border-color:#e65f47}}.card h2{{font:700 24px/1.2 Playfair Display,Georgia,serif;margin:10px 0}}.card p{{color:#654a45;margin:0 0 14px}}.card-meta{{color:#806b65;font-size:13px;margin-top:auto}}.card b{{color:#e65f47;margin-top:14px}}footer{{border-top:1px solid #f2d9d1;text-align:center;padding:28px;color:#806b65}}@media(max-width:800px){{.header{{align-items:flex-start;flex-direction:column}}.hero h1{{font-size:46px}}.cards{{grid-template-columns:1fr}}}}</style></head><body><div class="topbar"><strong>Doce &amp; Lucro</strong><a href="https://t.me/docelucro">Entrar na comunidade →</a></div><header class="header"><a class="brand" href="/"><span>DG</span> DoceGestor</a><nav><a href="/">O app</a><a href="/#recursos">Recursos</a><a href="/#como-funciona">Como funciona</a><a href="/blog/">Blog</a><a href="/receitas/">Receitas</a><a href="/ebooks/">E-books</a><a class="buy" href="{MARKET_URL}">Comprar agora</a></nav></header><section class="hero"><div class="hero-inner"><div class="eyebrow">Conteúdo para vender com clareza</div><h1>O blog para deixar sua confeitaria <em>mais segura.</em></h1><p>Guias práticos para calcular preços, organizar encomendas, controlar custos e aumentar o lucro da sua confeitaria.</p></div></section><main class="cards">{cards}</main><footer class="dl-footer"><div><strong>DoceGestor</strong> · Gestão simples para confeitarias</div><div><a href="/">Início</a> · <a href="/blog/">Blog</a> · <a href="/receitas/">Receitas</a> · <a href="/ebooks/">E-books</a></div><div>Desenvolvido por <a href="https://saulomgg.github.io" target="_blank" rel="noopener noreferrer">saulomgg</a></div></footer></body></html>'''
def update_sitemap(registry):
    p=ROOT/'sitemap.xml'; t=p.read_text(encoding='utf-8'); t=re.sub(r'\s*<url><loc>https://docegestor\.github\.io/blog/[^<]+</loc>.*?</url>','',t,flags=re.S); entries=''.join(f'  <url><loc>{BASE_URL}/blog/{esc(x["slug"])}/</loc><lastmod>{x["published"]}</lastmod><priority>0.8</priority></url>\n' for x in registry); p.write_text(t.replace('</urlset>',entries+'</urlset>'),encoding='utf-8')
def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--limit',type=int,default=1); ap.add_argument('--input',type=Path); ap.add_argument('--dry-run',action='store_true'); args=ap.parse_args()
    if args.limit<0 or args.limit>3: raise RuntimeError('--limit deve estar entre 0 e 3.')
    raw=load(args.input,[]) if args.input else load(QUEUE,[]); raw=[raw] if isinstance(raw,dict) else raw; registry=load(REGISTRY,[]); known={x.get('slug') for x in registry}
    for old in load(LEGACY_REGISTRY,[]):
        if old.get('slug') and old['slug'] not in known: registry.append({'slug':old['slug'],'title':old.get('title',''),'description':old.get('description',''),'category':old.get('category','Gestão financeira'),'published':old.get('published',dt.date.today().isoformat())}); known.add(old['slug'])
    selected=[]
    for item in raw:
        a=normalize(item); validate(a)
        if a['slug'] not in known: selected.append(a)
    selected=selected[:args.limit]; today=dt.date.today().isoformat()
    if args.dry_run: print(f'Artigos validados (dry-run): {len(selected)}'); return 0
    for a in selected:
        out=ROOT/'blog'/a['slug']; out.mkdir(parents=True,exist_ok=False); cover=out/'capa.svg'; write_cover(cover,a['title'],a['category']); image=f'{BASE_URL}/blog/{a["slug"]}/capa.svg'; a['image']=image; (out/'index.html').write_text(render(a,today,registry,image),encoding='utf-8'); registry.insert(0,{'slug':a['slug'],'title':a['title'],'description':a['description'],'category':a['category'],'published':today,'image':image})
    if selected or registry!=load(REGISTRY,[]): REGISTRY.write_text(json.dumps(registry,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    (ROOT/'blog/index.html').write_text(render_blog(registry),encoding='utf-8'); update_sitemap(registry)
    if args.input and args.input.exists(): args.input.write_text(json.dumps([x for x in raw if slugify(str(x.get('slug') or x.get('title') or '')) not in {a['slug'] for a in selected}],ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(f'Artigos publicados no blog: {len(selected)}')
if __name__=='__main__':
    try: main()
    except Exception as e: print(f'ERRO: {e}',file=__import__('sys').stderr); raise
